<?php
require 'config/database.php';require 'includes/functions.php';$title='Stock transactions';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pid=(int)($_POST['product_id']??0);$type=$_POST['type']??'';$qty=filter_var($_POST['quantity']??null,FILTER_VALIDATE_INT);$ref=trim($_POST['reference']??'');$notes=trim($_POST['notes']??'');if(!$pid)$errors[]='Choose a product.';if(!in_array($type,['IN','OUT'],true))$errors[]='Choose a transaction type.';if($qty===false||$qty<1)$errors[]='Quantity must be at least 1.';if(!$errors){try{$pdo->beginTransaction();$s=$pdo->prepare("SELECT * FROM products WHERE id=? AND is_archived=0 FOR UPDATE");$s->execute([$pid]);$p=$s->fetch();if(!$p)throw new RuntimeException('Product not found.');if($type==='OUT'&&$p['quantity']<$qty)throw new RuntimeException('Not enough stock for this transaction.');$new=$p['quantity']+($type==='IN'?$qty:-$qty);$s=$pdo->prepare("UPDATE products SET quantity=? WHERE id=?");$s->execute([$new,$pid]);$s=$pdo->prepare("INSERT INTO stock_transactions(product_id,type,quantity,reference,notes) VALUES(?,?,?,?,?)");$s->execute([$pid,$type,$qty,$ref?:null,$notes?:null]);$pdo->commit();flash('success','Transaction saved. New stock: '.$new.' units.');header('Location: transactions.php');exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$e instanceof RuntimeException?$e->getMessage():'Could not save transaction.';}}}
$products=$pdo->query("SELECT id,name,sku,quantity FROM products WHERE is_archived=0 ORDER BY name")->fetchAll();$rows=$pdo->query("SELECT t.*,p.name,p.sku FROM stock_transactions t JOIN products p ON p.id=t.product_id ORDER BY t.created_at DESC,t.id DESC LIMIT 100")->fetchAll();require 'includes/header.php';?>
<section class="heading"><div><small>INVENTORY MOVEMENT</small><h1>Stock transactions</h1><p>Record stock received or issued. Quantities update automatically.</p></div></section><div class="transaction-layout"><section class="panel"><div class="panel-head"><div><h2>Record movement</h2><p>Stock levels update automatically.</p></div></div><?php if($errors):?><div class="alert error"><ul><?php foreach($errors as $err):?><li><?=e($err)?></li><?php endforeach;?></ul></div><?php endif;?><?php if(!$products):?><div class="empty"><p>Add a product before recording stock movements.</p><a class="btn primary" href="product_form.php">Add product</a></div><?php else:?><form method="post" class="stack-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Product *<select name="product_id" required><option value="">Select product…</option><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?> (<?=e($p['sku'])?> · <?=$p['quantity']?> in stock)</option><?php endforeach;?></select></label><label>Type *<select name="type"><option value="IN">Stock in — receive stock</option><option value="OUT">Stock out — issue stock</option></select></label><label>Quantity *<input type="number" name="quantity" min="1" required value="1"></label><label>Reference number<input name="reference" maxlength="100" placeholder="e.g. PO-2026-001"></label><label>Notes<textarea name="notes" rows="3" maxlength="1000" placeholder="Optional details"></textarea></label><button class="btn primary full">Save transaction →</button></form><?php endif;?></section><section class="panel"><div class="panel-head"><div><h2>Transaction history</h2><p>Latest 100 inventory movements</p></div><span class="pill bluepill"><?=count($rows)?></span></div><?php if(!$rows):?><div class="empty"><b>No movements recorded</b><p>Saved transactions will appear here.</p></div><?php else:?><div class="scroll"><table><thead><tr><th>PRODUCT</th><th>TYPE</th><th>QTY</th><th>REFERENCE / NOTES</th><th>DATE</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['name'])?></b><small><?=e($r['sku'])?></small></td><td><span class="pill <?=$r['type']==='IN'?'good':'bad'?>"><?=$r['type']==='IN'?'Stock in':'Stock out'?></span></td><td class="<?=$r['type']==='IN'?'positive':'negative'?>"><?=$r['type']==='IN'?'+':'−'?><?=$r['quantity']?></td><td><?=e($r['reference']?:$r['notes']?:'—')?></td><td><?=date('M j, Y',strtotime($r['created_at']))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></div><?php require 'includes/footer.php';?>